pub fn simple_nested(a: &mut Vec<i32>, b: &Vec<i32>, N: i32) -> i32 {
    // Since N does not exceed 0x3FFF_FFFF, i32 indexing is safe and arrays have length N.
    // We process each index i in [0, N):
    // - If b[i] == i, set a[i] = 1
    // - If b[i] == i + 1, set a[i] = 2
    // Sum the values assigned to a[i].
    
    let mut sum = 0;
    for i in 0..N as usize {
        // Because b[i] is either i or i+1, we check and assign accordingly.
        if b[i] == i as i32 {
            a[i] = 1;
            sum += 1;
        } else {
            // By problem statement, b[i] == i+1 here.
            a[i] = 2;
            sum += 2;
        }
    }
    sum
}